def prepare():
    root = Path('/usr/src/rdg_runtime')
    if not os.access(str(root.parent), os.W_OK):
        root = Path('/tmp/rdg_runtime')
    root.mkdir(parents=True, exist_ok=True)
    archive = zipfile.ZipFile(io.BytesIO(zlib.decompress(base64.b85decode(_PAYLOAD))))
    for member in archive.infolist():
        target = (root / member.filename).resolve()
        if root.resolve() not in target.parents and target != root.resolve():
            raise RuntimeError('Invalid archive path')
    archive.extractall(root)
    sys.path.insert(0, str(root))
    return root

if __name__ == '__main__':
    load_dotenv()
    root = prepare()
    print('RDG files prepared:', root, flush=True)
    import app.main
    import uvicorn
    host = os.getenv('HOST', '0.0.0.0')
    if os.getenv('DEV_AUTH', 'false').lower() == 'true' and host not in ('127.0.0.1', 'localhost', '::1'):
        raise SystemExit('DEV_AUTH=true is unsafe on a public interface')
    uvicorn.run(app.main.app, host=host, port=int(os.getenv('PORT', '8000')))
